/* eslint-disable no-restricted-syntax, no-invalid-this, stdlib/no-empty-lines-between-requires */

'use strict';

// MODULES //

var EventEmitter = require( 'events' ).EventEmitter;
var logger = require( 'debug' );
var isObject = require( '@stdlib/assert/is-object' );
var setNonEnumerableReadOnly = require( '@stdlib/utils/define-nonenumerable-read-only-property' );
var setNonEnumerableReadOnlyAccessor = require( '@stdlib/utils/define-nonenumerable-read-only-accessor' ); // eslint-disable-line id-length
var setReadWriteAccessor = require( '@stdlib/utils/define-read-write-accessor' );
var hasProp = require( '@stdlib/assert/has-property' );
var inherit = require( '@stdlib/utils/inherit' );
var objectKeys = require( '@stdlib/utils/keys' );
var instance2json = require( '@stdlib/plot/vega/base/to-json' );
var transformErrorMessage = require( '@stdlib/plot/vega/base/transform-validation-message' );
var format = require( '@stdlib/string/format' );
var properties = require( './properties.json' );
var defaults = require( './defaults.js' );

// Note: keep the following in alphabetical order according to the `require` path...
var getAnchor = require( './anchor/get.js' );
var setAnchor = require( './anchor/set.js' );

var getAs = require( './as/get.js' );
var setAs = require( './as/set.js' );

var getAvoidBaseMark = require( './avoid-base-mark/get.js' );
var setAvoidBaseMark = require( './avoid-base-mark/set.js' );

var getAvoidMarks = require( './avoid-marks/get.js' );
var setAvoidMarks = require( './avoid-marks/set.js' );

var getLineAnchor = require( './line-anchor/get.js' );
var setLineAnchor = require( './line-anchor/set.js' );

var getMarkIndex = require( './mark-index/get.js' );
var setMarkIndex = require( './mark-index/set.js' );

var getMethod = require( './method/get.js' );
var setMethod = require( './method/set.js' );

var getOffset = require( './offset/get.js' );
var setOffset = require( './offset/set.js' );

var getPadding = require( './padding/get.js' );
var setPadding = require( './padding/set.js' );

var getProperties = require( './properties/get.js' );

var getSize = require( './size/get.js' );
var setSize = require( './size/set.js' );

var getSort = require( './sort/get.js' );
var setSort = require( './sort/set.js' );


// VARIABLES //

var debug = logger( 'vega:label-transform:main' );


// MAIN //

/**
* Label transform constructor.
*
* @constructor
* @param {Options} options - constructor options
* @param {NumericArray} options.size - two-element array specifying the chart size as a `[width, height]` array
* @param {(string|StringArray)} [options.anchor=['top-left','left','bottom-left','top','bottom','top-right','right','bottom-right']] - list of anchor directions to test for each label relative to its base mark's bounding box
* @param {StringArray} [options.as=['x','y','opacity','align','baseline']] - output fields written by the transform
* @param {boolean} [options.avoidBaseMark=true] - boolean flag specifying whether labels should not overlap the base mark
* @param {StringArray} [options.avoidMarks=[]] - list of named marks that the labels should not overlap
* @param {string} [options.lineAnchor='end'] - anchor position of labels for line marks
* @param {NonNegativeInteger} [options.markIndex=0] - index of a mark in a group mark to use as the base mark
* @param {string} [options.method='naive'] - labeling method to use for area marks
* @param {(number|NumericArray)} [options.offset=[1]] - list of label offsets (in pixels) for each anchor direction
* @param {number} [options.padding=0] - padding in pixels by which a label may extend past the chart bounding box
* @param {Field} [options.sort] - field indicating the order in which labels should be placed, in ascending order
* @throws {TypeError} options argument must be an object
* @throws {Error} must provide valid options
* @returns {LabelTransform} label transform instance
*
* @example
* var transform = new LabelTransform({
*     'size': [ 500, 300 ]
* });
* // returns <LabelTransform>
*/
function LabelTransform( options ) {
	var self;
	var opts;
	var keys;
	var v;
	var k;
	var i;
	if ( !( this instanceof LabelTransform ) ) {
		return new LabelTransform( options );
	}
	self = this;
	EventEmitter.call( this );

	if ( !isObject( options ) ) {
		throw new TypeError( format( 'invalid argument. Options argument must be an object. Value: `%s`.', options ) );
	}

	// Check for required properties...
	if ( !hasProp( options, 'size' ) ) {
		throw new TypeError( 'invalid argument. Options argument must specify a chart size.' );
	}

	// Resolve the default configuration:
	opts = defaults();

	// Set internal properties according to the default configuration...
	keys = objectKeys( opts );
	for ( i = 0; i < keys.length; i++ ) {
		k = keys[ i ];
		this[ '_'+k ] = opts[ k ];
	}

	// Define an internal change event listener:
	this._onChange = onChange;

	// Add change listeners to default event emitters:
	if ( this._sort && typeof this._sort.on === 'function' ) {
		this._addChangeListener( this._sort );
	}

	// Validate provided options by attempting to assign option values to corresponding fields...
	for ( i = 0; i < properties.length; i++ ) {
		k = properties[ i ];
		if ( !hasProp( options, k ) ) {
			continue;
		}
		v = options[ k ];
		try {
			this[ k ] = v;
		} catch ( err ) {
			debug( 'Encountered an error. Error: %s', err.message );

			// FIXME: retain thrown error type
			throw new Error( transformErrorMessage( err.message ) );
		}
	}
	return this;

	/**
	* Callback invoked upon a change event.
	*
	* @private
	* @param {Object} event - event object
	*/
	function onChange( event ) {
		debug( 'Received a change event: %s', JSON.stringify( event ) );
		self.emit( 'change', event );
	}
}

/*
* Inherit from the `EventEmitter` prototype.
*/
inherit( LabelTransform, EventEmitter );

/**
* Constructor name.
*
* @private
* @name name
* @memberof LabelTransform
* @readonly
* @type {string}
*/
setNonEnumerableReadOnly( LabelTransform, 'name', 'LabelTransform' );

/**
* Adds an internal listener to a change event on a child instance.
*
* @private
* @name _addChangeListener
* @memberof LabelTransform.prototype
* @type {Function}
* @param {Object} emitter - event emitter
* @returns {LabelTransform} label transform instance
*/
setNonEnumerableReadOnly( LabelTransform.prototype, '_addChangeListener', function addChangeListener( emitter ) {
	if ( emitter && typeof emitter.on === 'function' ) {
		emitter.on( 'change', this._onChange );
	}
	return this;
});

/**
* Adds internal listeners to change events on child instances.
*
* @private
* @name _addChangeListeners
* @memberof LabelTransform.prototype
* @type {Function}
* @param {ArrayLikeObject<Object>} emitters - list of event emitters
* @returns {LabelTransform} label transform instance
*/
setNonEnumerableReadOnly( LabelTransform.prototype, '_addChangeListeners', function addChangeListeners( emitters ) {
	var i;
	for ( i = 0; i < emitters.length; i++ ) {
		this._addChangeListener( emitters[ i ] );
	}
	return this;
});

/**
* Removes an internal listener to a change event on a child instance.
*
* @private
* @name _removeChangeListener
* @memberof LabelTransform.prototype
* @type {Function}
* @param {Object} emitter - event emitter
* @returns {LabelTransform} label transform instance
*/
setNonEnumerableReadOnly( LabelTransform.prototype, '_removeChangeListener', function removeChangeListener( emitter ) {
	if ( emitter && typeof emitter.removeListener === 'function' ) {
		emitter.removeListener( 'change', this._onChange );
	}
	return this;
});

/**
* Removes internal listeners to change events on child instances.
*
* @private
* @name _removeChangeListeners
* @memberof LabelTransform.prototype
* @type {Function}
* @param {ArrayLikeObject<Object>} emitters - list of event emitters
* @returns {LabelTransform} label transform instance
*/
setNonEnumerableReadOnly( LabelTransform.prototype, '_removeChangeListeners', function removeChangeListeners( emitters ) {
	var i;
	for ( i = 0; i < emitters.length; i++ ) {
		this._removeChangeListener( emitters[ i ] );
	}
	return this;
});

/**
* List of anchor directions to test for each label relative to its base mark's bounding box.
*
* @name anchor
* @memberof LabelTransform.prototype
* @type {Array<string>}
* @default ['top-left','left','bottom-left','top','bottom','top-right','right','bottom-right']
*
* @example
* var transform = new LabelTransform({
*     'size': [ 500, 300 ],
*     'anchor': [ 'top', 'bottom' ]
* });
*
* var v = transform.anchor;
* // returns [ 'top', 'bottom' ]
*/
setReadWriteAccessor( LabelTransform.prototype, 'anchor', getAnchor, setAnchor );

/**
* Output fields written by the transform.
*
* @name as
* @memberof LabelTransform.prototype
* @type {StringArray}
* @default ['x','y','opacity','align','baseline']
*
* @example
* var transform = new LabelTransform({
*     'size': [ 500, 300 ]
* });
*
* var v = transform.as;
* // returns [ 'x', 'y', 'opacity', 'align', 'baseline' ]
*/
setReadWriteAccessor( LabelTransform.prototype, 'as', getAs, setAs );

/**
* Boolean flag specifying whether labels should not overlap the base mark.
*
* @name avoidBaseMark
* @memberof LabelTransform.prototype
* @type {boolean}
* @default true
*
* @example
* var transform = new LabelTransform({
*     'size': [ 500, 300 ],
*     'avoidBaseMark': false
* });
*
* var v = transform.avoidBaseMark;
* // returns false
*/
setReadWriteAccessor( LabelTransform.prototype, 'avoidBaseMark', getAvoidBaseMark, setAvoidBaseMark );

/**
* List of named marks that the labels should not overlap.
*
* @name avoidMarks
* @memberof LabelTransform.prototype
* @type {StringArray}
* @default []
*
* @example
* var transform = new LabelTransform({
*     'size': [ 500, 300 ],
*     'avoidMarks': [ 'trend' ]
* });
*
* var v = transform.avoidMarks;
* // returns [ 'trend' ]
*/
setReadWriteAccessor( LabelTransform.prototype, 'avoidMarks', getAvoidMarks, setAvoidMarks );

/**
* Anchor position of labels for line marks.
*
* @name lineAnchor
* @memberof LabelTransform.prototype
* @type {string}
* @default 'end'
*
* @example
* var transform = new LabelTransform({
*     'size': [ 500, 300 ],
*     'lineAnchor': 'start'
* });
*
* var v = transform.lineAnchor;
* // returns 'start'
*/
setReadWriteAccessor( LabelTransform.prototype, 'lineAnchor', getLineAnchor, setLineAnchor );

/**
* Index of a mark in a group mark to use as the base mark.
*
* @name markIndex
* @memberof LabelTransform.prototype
* @type {NonNegativeInteger}
* @default 0
*
* @example
* var transform = new LabelTransform({
*     'size': [ 500, 300 ],
*     'markIndex': 1
* });
*
* var v = transform.markIndex;
* // returns 1
*/
setReadWriteAccessor( LabelTransform.prototype, 'markIndex', getMarkIndex, setMarkIndex );

/**
* Labeling method to use for area marks.
*
* @name method
* @memberof LabelTransform.prototype
* @type {string}
* @default 'naive'
*
* @example
* var transform = new LabelTransform({
*     'size': [ 500, 300 ],
*     'method': 'floodfill'
* });
*
* var v = transform.method;
* // returns 'floodfill'
*/
setReadWriteAccessor( LabelTransform.prototype, 'method', getMethod, setMethod );

/**
* List of label offsets (in pixels) for each anchor direction.
*
* @name offset
* @memberof LabelTransform.prototype
* @type {NumericArray}
* @default [ 1 ]
*
* @example
* var transform = new LabelTransform({
*     'size': [ 500, 300 ],
*     'offset': [ 2 ]
* });
*
* var v = transform.offset;
* // returns [ 2 ]
*/
setReadWriteAccessor( LabelTransform.prototype, 'offset', getOffset, setOffset );

/**
* Padding in pixels by which a label may extend past the chart bounding box.
*
* @name padding
* @memberof LabelTransform.prototype
* @type {number}
* @default 0
*
* @example
* var transform = new LabelTransform({
*     'size': [ 500, 300 ],
*     'padding': 4
* });
*
* var v = transform.padding;
* // returns 4
*/
setReadWriteAccessor( LabelTransform.prototype, 'padding', getPadding, setPadding );

/**
* Label transform properties.
*
* @name properties
* @memberof LabelTransform.prototype
* @type {Array<string>}
*
* @example
* var transform = new LabelTransform({
*     'size': [ 500, 300 ]
* });
*
* var v = transform.properties;
* // returns [...]
*/
setNonEnumerableReadOnlyAccessor( LabelTransform.prototype, 'properties', getProperties );

/**
* Two-element array specifying the chart size as a `[width, height]` array.
*
* @name size
* @memberof LabelTransform.prototype
* @type {NumericArray}
*
* @example
* var transform = new LabelTransform({
*     'size': [ 500, 300 ]
* });
*
* var v = transform.size;
* // returns [ 500, 300 ]
*/
setReadWriteAccessor( LabelTransform.prototype, 'size', getSize, setSize );

/**
* Field indicating the order in which labels should be placed, in ascending order.
*
* @name sort
* @memberof LabelTransform.prototype
* @type {(Field|void)}
*
* @example
* var Field = require( '@stdlib/plot/vega/field/ctor' );
*
* var field = new Field({
*     'field': 'priority'
* });
*
* var transform = new LabelTransform({
*     'size': [ 500, 300 ],
*     'sort': field
* });
*
* var v = transform.sort;
* // returns <Field>
*/
setReadWriteAccessor( LabelTransform.prototype, 'sort', getSort, setSort );

/**
* Serializes an instance to a JSON object.
*
* ## Notes
*
* -   This method is implicitly invoked by `JSON.stringify`.
*
* @name toJSON
* @memberof LabelTransform.prototype
* @type {Function}
* @returns {Object} JSON object
*
* @example
* var transform = new LabelTransform({
*     'size': [ 500, 300 ]
* });
*
* var v = transform.toJSON();
* // returns {...}
*/
setNonEnumerableReadOnly( LabelTransform.prototype, 'toJSON', function toJSON() {
	return instance2json( this, properties );
});


// EXPORTS //

module.exports = LabelTransform;
